#!/bin/bash
# نشر EWA_Core (التوكن الأصلي) من Termux
# السقف: 21,000,000 EWA | التأسيس: 3,000,000 على محفظة المؤسس | الباقي 18M غير مسكوك
# الخطوات:
# 1) ولّد مفتاح جديد: cast wallet new  (المفتاح اللي اتلصق في الشات محروق - متستخدموش)
# 2) موّل المفتاح الجديد بجزء صغير ETH للغاز على Base
# 3) قبل التشغيل:  export PK=0x....  (مفتاحك الجديد - مايتكتبش في الملف)
# 4) نفّذ:  bash deployments/deploy-ewa.sh
# 5) بعد ما تخلص:  unset PK && history -c
# 6) ابعت عنوان العقد لباليريون عشان يوصّله في العقود الـ48

export RPC=https://mainnet.base.org
if [ -z "$PK" ]; then echo "حط مفتاحك الأول: export PK=0x..."; exit 1; fi

# ---------------- CONFIG ----------------
MAX_SUPPLY_WEI=21000000000000000000000000   # 21,000,000 * 1e18
FOUNDER=0xE9B0CebeF9e93cAc7727A06D5ED5f8e3AE71e5F8
MINT_WEI=3000000000000000000000000           # 3,000,000 * 1e18
# ---------------- END CONFIG ----------------

DEPLOYER=$(cast wallet address --private-key $PK)
echo "deployer: $DEPLOYER"

echo "=== 1/4 نشر EWA_Core ==="

ARGS=$(cast abi-encode "constructor(uint256)" $MAX_SUPPLY_WEI)
CORE=$(cast send --rpc-url $RPC --private-key $PK --create ${BYTECODE}${ARGS} | grep -i contractAddress | awk '{print $2}')
if [ -z "$CORE" ]; then echo "فشل استخراج العنوان - راجع مخرجات النشر فوق"; exit 1; fi
echo "EWA_Core = $CORE"

echo "=== 2/4 منح صلاحية السك للمنشر ==="
cast send $CORE "grantMinter(address)" $DEPLOYER --rpc-url $RPC --private-key $PK

echo "=== 3/4 سك 3,000,000 EWA للمؤسس ==="
cast send $CORE "mint(address,uint256)" $FOUNDER $MINT_WEI --rpc-url $RPC --private-key $PK

echo "=== 4/4 سحب صلاحية السك (قفل - الأدمن يقدر يرجعها) ==="
cast send $CORE "revokeMinter(address)" $DEPLOYER --rpc-url $RPC --private-key $PK

echo "=== تحقق ==="
echo "totalSupply: $(cast call $CORE "totalSupply()(uint256)" --rpc-url $RPC)"
echo "founder bal: $(cast call $CORE "balanceOf(address)(uint256)" $FOUNDER --rpc-url $RPC)"
echo "MAX_SUPPLY : $(cast call $CORE "MAX_SUPPLY()(uint256)" --rpc-url $RPC)"
echo "admin      : $(cast call $CORE "admin()(address)" --rpc-url $RPC)"
echo ""
echo "تم. EWA_Core = $CORE"
